input.content:
const { add } = require('./index');
const assert = require('assert');

console.log('Running additional tests for add function:');

// Test positive numbers
assert.strictEqual(add(2, 2), 4, '2 + 2 should equal 4');
console.log('✓ 2 + 2 = 4');

// Test with zero
assert.strictEqual(add(5, 0), 5, '5 + 0 should equal 5');
console.log('✓ 5 + 0 = 5');

// Test negative numbers
assert.strictEqual(add(-3, 7), 4, '-3 + 7 should equal 4');
console.log('✓ -3 + 7 = 4');

// Test both negative numbers
assert.strictEqual(add(-5, -3), -8, '-5 + -3 should equal -8');
console.log('✓ -5 + -3 = -8');

// Test decimal numbers
assert.strictEqual(add(2.5, 1.5), 4, '2.5 + 1.5 should equal 4');
console.log('✓ 2.5 + 1.5 = 4');

console.log('\nAll additional tests passed!');
console.log('Original test also passes:');
require('./test.js');

